pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.sendMoney(address(c), amount, "") {} catch { return; }
        uint beforeBalance = address(c).balance;
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        uint ownerBefore = owner.balance;
        try c.withdrawAll() {} catch { return; }
        uint afterBalance = address(c).balance;
        uint ownerAfter = owner.balance;
        assertTrue(afterBalance == 0 && ownerAfter - ownerBefore == beforeBalance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
